/// Arsenal's patch: every player list entry's name and ping (milliseconds; 0 before the server's first update).
pub(super) fn arsenal_latencies(&self) -> Vec<(String, i32)> {
    self.remote.as_ref().map_or_else(Vec::new, |r| r.tab_players.values().map(|t| (t.name.clone(), t.latency)).collect())
}

/// The window's player's status as a native mod reads it (Arsenal's patch).
#[allow(dead_code)]
#[derive(Clone, Debug)]
pub(crate) struct NativeStatus {
    /// The attack charge, 0..1 (1 is a full hit).
    pub(crate) attack: f32,
    /// Each effect: its id, level (0 is I) and ticks left.
    pub(crate) effects: Vec<(String, i32, i32)>,
    /// The own ping the player list gives, in milliseconds.
    pub(crate) ping: Option<i32>,
    /// Every player list entry's name and ping.
    pub(crate) latencies: Vec<(String, i32)>,
    /// The window's player's entity id (0 on the title screen).
    pub(crate) own_id: u32,
}

/// The window's player's attack charge, effects and pings (Arsenal's patch).
pub(super) fn arsenal_status(&self) -> NativeStatus {
    NativeStatus {
        attack: self.attack_strength_scale(),
        effects: self.potions.effects.list.iter().map(|e| (e.id.to_string(), e.amplifier, e.duration)).collect(),
        ping: self.own_latency(),
        latencies: self.arsenal_latencies(),
        own_id: self.player.as_ref().map_or(0, |p| p.entity_id as u32),
    }
}
